mapper.select:
SELECT id, user_id, goal_month, title, target_category, reduction_ratio, baseline_amount, monthly_save, status, actual_saved, CAST(created_at AS TIMESTAMP) AS created_at, CAST(updated_at AS TIMESTAMP) AS updated_at FROM monthly_goals WHERE user_id = #{userId}
AND status = #{status.value}
ORDER BY goal_month ASC, id ASC
